import {ELEMENTS} from './elements-data.js';
export const FAMILY={'Nonmetal':'Неметал','Noble gas':'Благородний газ','Alkali metal':'Лужний метал','Alkaline earth metal':'Лужноземельний метал','Metalloid':'Металоїд','Halogen':'Галоген','Transition metal':'Перехідний метал','Post-transition metal':'Постперехідний метал','Lanthanide':'Лантаноїд','Actinide':'Актиноїд'};
const aliases={H:'водень',C:'вуглець',N:'азот',O:'кисень',F:'фтор',Si:'кремній',S:'сірка',Fe:'залізо',Cu:'мідь',Ag:'срібло',Sn:'олово',Sb:'сурма',Au:'золото',Hg:'ртуть',Pb:'свинець'};
const facts={
 H:'Два атоми Гідрогену й один Оксигену утворюють молекулу води H₂O. Водень також потрібний для виробництва аміаку.',
 He:'Гелій дуже мало реагує з іншими речовинами. Рідкий гелій використовують для охолодження надпровідних магнітів.',
 Li:'У літій-іонному акумуляторі заряд переносять іони літію. Його робота залежить від матеріалів обох електродів.',
 Be:'Берилій легкий і жорсткий. Його сплави застосовують у точних приладах.',
 B:'Сполуки Бору входять до боросилікатного скла, стійкого до різких змін температури.',
 C:'Графіт і алмаз складаються з Карбону. Різне розташування атомів створює дуже різні властивості.',
 N:'Азот N₂ становить приблизно 78% об’єму сухого повітря. Рослини зазвичай засвоюють Нітроген у складі сполук.',
 O:'Кисень O₂ підтримує горіння, але сам не є паливом. Він також потрібний для клітинного дихання.',
 F:'Фтор F₂ і флуорид-іон F⁻ мають різні властивості. У зубних пастах використовують флуоридні сполуки.',
 Ne:'Електричний розряд у неоні дає червоно-помаранчеве світло. Інші кольори вивісок отримують іншими способами.',
 Na:'Натрій — метал, а кухонна сіль NaCl — сполука. Властивості сполуки не дорівнюють властивостям її елементів.',
 Mg:'Магній застосовують у легких сплавах. Його іон також міститься в центрі молекули хлорофілу.',
 Al:'Алюміній легкий; тонка оксидна плівка на його поверхні захищає метал від подальшого окиснення.',
 Si:'Кремній — напівпровідник для мікросхем. Силіцій діоксид SiO₂ — інша речовина, важлива для скла.',
 P:'Фосфати потрібні рослинам і входять до складу багатьох добрив. Фосфор також є складником ДНК.',
 S:'Сульфур входить до деяких амінокислот. Сульфати й сірка як проста речовина мають різні властивості.',
 Cl:'Хлорвмісні реагенти застосовують для знезараження води за контрольованих умов. Відкриття елемента саме по собі не очищує воду.',
 Ar:'Аргон малоактивний. Захисне аргонове середовище використовують під час зварювання.',
 K:'Іони Калію важливі для рослин. Калійні добрива містять його сполуки, а не шматочки металу.',
 Ca:'Кальцій входить до складу вапняку CaCO₃. Його сполуки важливі для будівельних матеріалів.',
 Fe:'Сталь — сплав на основі заліза з вуглецем та іншими добавками. Її властивості залежать від складу й обробки.',
 Cu:'Мідь добре проводить електричний струм. Тому її широко використовують у проводах і електродвигунах.',
 Zn:'Цинкове покриття допомагає захищати сталь від корозії.',
 Ag:'Срібло дуже добре проводить електричний струм. Його застосовують у контактах та електроніці.',
 Au:'Золото стійке до багатьох хімічних впливів, тому тонкі золоті покриття використовують в електричних контактах.'
};
export function elementLesson(symbol){const e=ELEMENTS[symbol];if(!e)return null;const family=FAMILY[e.family]||e.family||'Класифікація уточнюється';return {...e,symbol,alias:aliases[symbol],family,state:({Solid:'Твердий',Liquid:'Рідкий',Gas:'Газоподібний',Unknown:'Не встановлено','Expected to be a Solid':'Очікується твердий стан','Expected to be a Gas':'Очікується газоподібний стан'}[e.state]||e.state||'Не встановлено'),fact:facts[symbol]||`Це ${e.number}-й елемент періодичної системи. Його атом визначають саме ${e.number} протонів у ядрі; зміна кількості нейтронів утворює інший ізотоп цього самого елемента.`,source:'https://pubchem.ncbi.nlm.nih.gov/element/'+e.number};}
export function lessonHTML(symbol){const e=elementLesson(symbol);if(!e)return '';return `<section class="element-lesson"><p class="element-alias">${e.alias?'Проста речовина: '+e.alias+'. ':''}${e.family}</p><dl><div><dt>Атомний номер</dt><dd>${e.number}</dd></div><div><dt>Атомна маса, u</dt><dd>${e.mass}</dd></div><div><dt>Протонів у ядрі</dt><dd>${e.number}</dd></div><div><dt>Електронів у нейтральному атомі</dt><dd>${e.number}</dd></div></dl><p><b>Коротко про елемент</b><br>${e.fact}</p><details><summary>Ще трохи хімії</summary><p>Стан за стандартних умов: ${e.state}. Для надважких елементів стан може бути передбаченим.</p><p>Ступені окиснення: ${e.oxidation||'дані не наведено'}. Це не те саме, що валентність.</p><p>Електронна конфігурація: <code>${e.configuration||'дані не наведено'}</code></p><p>Маса наведена за PubChem. Для радіоактивних елементів вона може стосуватися окремого ізотопу, а не середнього природного складу.</p><a href="${e.source}" target="_blank" rel="noopener noreferrer">Довідка PubChem</a></details><div class="element-check"><b>Перевір себе</b><p>Що означає число ${e.number} біля ${symbol}?</p><button data-answer="yes">Кількість протонів</button><button data-answer="no">Кількість нейтронів</button><p id="lesson-result" role="status"></p></div></section>`;}
